SourceCode.Declaration:
/// <summary>
/// TEMPORARY Phase-0 in-AOS render probe (plan WP-0.5). Proves the native SkiaSharp/HarfBuzz
/// assets load inside the AOS process, exercises the ZXing path with a ^BC barcode, attaches a
/// PNG via DocumentManagement, and logs loaded assembly identities for the ER-coexistence check.
/// DELETE BEFORE MERGE (plan constraint C-7).
/// Run: SysClassRunner: ?cmp=USMF&amp;mi=SysClassRunner&amp;cls=AAXZplRenderProbe
/// </summary>
internal final class AAXZplRenderProbe
{
    private const str PlainZpl   = '^XA^PW812^LL406^FO50,50^A0N,40,40^FDAAX Probe^FS^XZ';
    private const str BarcodeZpl = '^XA^PW812^LL406^FO50,50^BY3^BCN,100,Y,N,N^FD123456789^FS^XZ';
    private const str ProbeDocuTypeId = 'LBLPREV';
}

Method.Source:
public static void main(Args _args)
{
    // 1. Plain 4x2 render at 8 dpmm — proves native libSkiaSharp loads in-AOS (U-1).
    List plainPngs = AAXZplRenderService::renderToPngList(AAXZplRenderProbe::PlainZpl, 8);
    info(strFmt('Probe step 1 OK: plain ZPL rendered %1 PNG(s).', plainPngs.elements()));

    // 2. ^BC Code-128 render — exercises the ZXing path in-AOS (U-2/F34).
    List barcodePngs = AAXZplRenderService::renderToPngList(AAXZplRenderProbe::BarcodeZpl, 8);
    info(strFmt('Probe step 2 OK: barcode ZPL rendered %1 PNG(s).', barcodePngs.elements()));

    // 3. Attach the first PNG to a scratch record (WHSParameters) — proves the F25/F26 path.
    AAXZplRenderProbe::ensureProbeDocuType();

    ListEnumerator pngEnumerator = plainPngs.getEnumerator();
    if (pngEnumerator.moveNext())
    {
        System.IO.MemoryStream pngStream = AAXZplRenderService::pngContainerToStream(pngEnumerator.current());

        DocuRef docuRef = DocumentManagement::attachFileForRecord(
            WHSParameters::find(),
            AAXZplRenderProbe::ProbeDocuTypeId,
            pngStream,
            'AAXProbe.png',
            'AAX WP-0.5 probe label preview',
            'Temporary probe attachment - safe to delete.');

        info(strFmt('Probe step 3 OK: PNG attached, DocuRef RecId %1.', docuRef.RecId));
    }

    // 4. ER-coexistence: log loaded renderer-related assembly identities (U-2).
    AAXZplRenderProbe::logLoadedAssemblyIdentities();

    info('AAXZplRenderProbe: ALL STEPS GREEN (WP-0.5).');
}

/// <summary>
/// Idempotent, per-company creation of the LBLPREV document type (F26 — forward-pull of the
/// WP-2.5 ensureDocuType pattern; ActionClassId is REQUIRED or attachFile() throws, F25).
/// </summary>
private static void ensureProbeDocuType()
{
    if (!DocuType::find(AAXZplRenderProbe::ProbeDocuTypeId))
    {
        DocuType docuType;

        ttsbegin;
        docuType.TypeId        = AAXZplRenderProbe::ProbeDocuTypeId;
        docuType.Name          = "@AAXWarehouseTools:DocuTypeLabelPreview";
        docuType.TypeGroup     = DocuTypeGroup::File;
        docuType.FilePlace     = DocuFilePlace::Archive;
        docuType.ActionClassId = classNum(DocuActionFile);
        docuType.insert();
        ttscommit;

        info(strFmt('Probe: created document type %1.', AAXZplRenderProbe::ProbeDocuTypeId));
    }
}

/// <summary>
/// Logs the full names of renderer-related assemblies loaded in this AOS process,
/// for the ER side-by-side identity check (U-2: SkiaSharp and ZXing vs ElectronicReporting).
/// </summary>
private static void logLoadedAssemblyIdentities()
{
    System.AppDomain currentDomain = System.AppDomain::get_CurrentDomain();
    System.Array loadedAssemblies = currentDomain.GetAssemblies();
    int assemblyCount = loadedAssemblies.get_Length();

    for (int i = 0; i < assemblyCount; i++)
    {
        System.Reflection.Assembly assembly = loadedAssemblies.GetValue(i);
        str fullName = assembly.get_FullName();

        if (AAXZplRenderProbe::isRendererRelated(fullName))
        {
            info(strFmt('Loaded: %1', fullName));
        }
    }
}

private static boolean startsWith(str _value, str _prefix)
{
    return strLen(_value) >= strLen(_prefix)
        && subStr(_value, 1, strLen(_prefix)) == _prefix;
}
